    # Make the wall lines horizontal. Transposition handles vertical walls.
    row_score = max((sum(v == 8 for v in row) for row in grid), default=0)
    col_score = max((sum(grid[r][c] == 8 for r in range(h))
                     for c in range(w)), default=0)
    transposed = col_score > row_score
    a = [list(row) for row in zip(*grid)] if transposed else [row[:] for row in grid]
    H, W = len(a), len(a[0])

    seed = next(((r, c) for r in range(H) for c in range(W) if a[r][c] == 2), None)
    if seed is None:
        return grid
    sr, sc = seed

    walls = [r for r in range(H)
             if sum(v == 8 for v in a[r]) >= max(3, W // 2)]
    if not walls:
        return grid

    # Travel from the seed toward the wall lines.
    direction = 1 if sum(r > sr for r in walls) >= sum(r < sr for r in walls) else -1
    walls = sorted((r for r in walls if (r - sr) * direction > 0),
                   reverse=(direction < 0))
    if not walls:
        return grid

    gaps = {r: [c for c in range(W) if a[r][c] != 8] for r in walls}
    out = [row[:] for row in a]

    def paint(r, c):
