            out[r][c] = 2

    first = walls[0]
    g = gaps[first]
    if g:
        for c in range(min([sc] + g), max([sc] + g) + 1):
            paint(first - direction, c)
        for c in g:
            paint(first, c)

    for i in range(len(walls) - 1):
        r1, r2 = walls[i], walls[i + 1]
        g1, g2 = gaps[r1], gaps[r2]
        for c in g1:
            r = r1 + direction
            while r != r2:
